--- launch/planning ---
"""Packing clock: shift windows, pack rates and remaining copies, read from the portal files.

The launch plan workbook holds a shift table (rows like 'Saturday | 06:00–22:00') and an editions
table (product, packed, rate per hour). Sheets and columns are found by their headers, so a new
version of the plan is read without code changes. Packed copies come from the pack-out log when it
is newer than the plan. Nothing about Soony is written here.

A packed figure carries the time it was counted when its sheet states one ('status 2026-11-20
18:00', 'Saturday 13:00') or, for the pack-out log, the end of its last day. From then on the
lines are assumed to pack at their plan rate inside shifts (the plan's own assumption), so a status
from Saturday noon still says how far the cell is on Sunday. Parts shortfalls are separate: they
stop a line early (line_stops).
"""

from __future__ import annotations

import csv
import re
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta
from pathlib import Path
from typing import Any
from zoneinfo import ZoneInfo

_TIMES = re.compile(r"(\d{1,2}):(\d{2})\s*[–—-]\s*(\d{1,2}):(\d{2})")
_STAMP_ISO = re.compile(r"(\d{4}-\d{2}-\d{2})[ T](\d{1,2}):(\d{2})")
_STAMP_DAY = re.compile(r"\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\s+(\d{1,2}):(\d{2})", re.I)
# The challenge brief's shifts, used only when no plan workbook states any: no night shift.
DEFAULT_SHIFTS = [("saturday", "06:00–22:00"), ("sunday", "06:00–20:00")]
WEEKDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]


@dataclass
class EditionPlan:
    product: str
    label: str | None = None
    day_one: float | None = None
    packed: float | None = None
    rate_per_hour: float | None = None
    packed_as_of: datetime | None = None  # when `packed` was counted, if a source says so
    packed_source: str | None = None  # the file (and sheet) the packed figure comes from

    @property
    def remaining(self) -> float | None:
        if self.day_one is None or self.packed is None:
            return None
        return max(self.day_one - self.packed, 0)


@dataclass
class PackClock:
    windows: list[tuple[datetime, datetime]] = field(default_factory=list)
    editions: dict[str, EditionPlan] = field(default_factory=dict)

    @property
    def launch(self) -> datetime | None:
        """Trucks leave when the last shift ends."""
        return self.windows[-1][1] if self.windows else None

    def hours_left(self, now: datetime) -> float:
        return sum(max((e - max(s, now)).total_seconds(), 0) for s, e in self.windows) / 3600

    def shift_hours_between(self, a: datetime, b: datetime) -> float:
        return sum(max((min(e, b) - max(s, a)).total_seconds(), 0) for s, e in self.windows) / 3600

    def _base(self, now: datetime, ed: EditionPlan) -> datetime:
        """Where projections start: the time the packed figure was counted, if earlier than now."""
        return ed.packed_as_of if ed.packed_as_of and ed.packed_as_of < now else now

    def remaining_at(self, now: datetime, product: str | None) -> float | None:
        """Copies still to pack at `now`: the counted figure, less the plan rate for the shift
        hours since it was counted."""
        ed = self.editions.get(product or "")
        if not ed or ed.remaining is None:
            return None
        if not ed.rate_per_hour:
            return ed.remaining
        return max(ed.remaining - ed.rate_per_hour * self.shift_hours_between(self._base(now, ed), now), 0)

    def finishes(self, now: datetime, product: str | None) -> datetime | None:
        """When the last copy is packed at plan rate; None if the shifts run out first."""
        ed = self.editions.get(product or "")
        if not ed or not ed.rate_per_hour or ed.remaining is None:
            return None
        base = self._base(now, ed)
        done = self.after_packing_hours(base, ed.remaining / ed.rate_per_hour)
        return max(done, now) if done else None

    def after_packing_hours(self, now: datetime, hours: float) -> datetime | None:
        """Wall-clock time once `hours` of packing from `now` are used up; None if they outlast
        the last shift. Night gaps between shifts are skipped."""
        left = max(hours, 0.0)
        for start, end in self.windows:
            begin = max(start, now)
            if begin >= end:
                continue
            avail = (end - begin).total_seconds() / 3600
            if left <= avail:
                return begin + timedelta(hours=left)
            left -= avail
        return None

    def line_stops(self, now: datetime, product: str | None, copies_short: float | None):
        """When a line runs out if `copies_short` of the remaining copies cannot be packed: it packs
        the others at its plan rate, inside shifts, then stops. None if nothing is short or the
        rate is unknown."""
        ed = self.editions.get(product or "")
        if not ed or not copies_short or not ed.rate_per_hour or ed.remaining is None:
            return None
        packable = max(ed.remaining - copies_short, 0)
        return self.after_packing_hours(self._base(now, ed), packable / ed.rate_per_hour)

    def slack_hours(self, now: datetime, product: str | None) -> float | None:
        ed = self.editions.get(product or "")
        left = self.remaining_at(now, product)
        if not ed or not ed.rate_per_hour or left is None:
            return None
        return round(self.hours_left(now) - left / ed.rate_per_hour, 1)


def _num(v: Any) -> float | None:
    if v is None or v == "":
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace(" ", "")
    if re.fullmatch(r"-?\d{1,3}(\.\d{3})+", s):  # '42.900' = 42,900
        s = s.replace(".", "")
    try:
        return float(s.replace(",", ""))
    except ValueError:
        return None


def _rows(path: Path) -> dict[str, list[tuple]]:
    try:
        import openpyxl

        wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
    except Exception:  # unreadable or missing workbook: no plan
        return {}
    out = {ws.title: [r for r in ws.iter_rows(values_only=True) if any(c is not None for c in r)]
           for ws in wb.worksheets}
    wb.close()
    return out


def _table(rows: list[tuple], *needles: str) -> tuple[dict[str, int], list[tuple]] | None:
    """The first header row that names every needle, with the rows below it."""
    for i, r in enumerate(rows):
        cells = [str(c or "").strip().lower() for c in r]
        if all(any(n in c for c in cells) for n in needles):
            return {c: j for j, c in enumerate(cells) if c}, rows[i + 1:]
    return None


def _col(header: dict[str, int], *needles: str) -> int | None:
    return next((j for c, j in header.items() if all(n in c for n in needles)), None)


def _stamp(text: str, launch: date | None, tz: ZoneInfo) -> datetime | None:
    """'status 2026-11-20 18:00' or 'Saturday 13:00' (the weekday of launch week) in a title."""
    m = _STAMP_ISO.search(text)
    if m:
        d = date.fromisoformat(m.group(1))
        return datetime(d.year, d.month, d.day, int(m.group(2)), int(m.group(3)), tzinfo=tz)
    m = _STAMP_DAY.search(text)
    if m and launch:
        on = launch - timedelta(days=(launch.weekday() - WEEKDAYS.index(m.group(1).lower())) % 7)
        return datetime(on.year, on.month, on.day, int(m.group(2)), int(m.group(3)), tzinfo=tz)
    return None


def default_windows(launch: date, tz: ZoneInfo) -> list[tuple[datetime, datetime]]:
    return _windows([("Day", "Shift"), *DEFAULT_SHIFTS], launch, tz)


def _windows(rows: list[tuple], launch: date | None, tz: ZoneInfo):
    found = _table(rows, "day", "shift")
    if not found or not launch:
        return []
    header, body = found
    dcol, scol = _col(header, "day"), _col(header, "shift")
    out = []
    for r in body:
        day = str(r[dcol] or "").strip().lower() if dcol is not None else ""
        m = _TIMES.search(str(r[scol] or "")) if scol is not None else None
        if day not in WEEKDAYS or not m:
            continue
        on = launch - timedelta(days=(launch.weekday() - WEEKDAYS.index(day)) % 7)
        h1, m1, h2, m2 = map(int, m.groups())
        start = datetime(on.year, on.month, on.day, h1, m1, tzinfo=tz)
        end = datetime(on.year, on.month, on.day, h2, m2, tzinfo=tz)
        out.append((start, end if end > start else end + timedelta(days=1)))
    return sorted(out)


def _read_csv(path: Path) -> list[dict]:
    try:
        with path.open(encoding="utf-8-sig", newline="") as fh:
            return list(csv.DictReader(fh))
    except OSError:
        return []


def _set_packed(ed: EditionPlan, n: float, at: datetime | None, source: str | None = None) -> None:
    """Packed copies only grow, so the highest figure is the newest; it keeps its own stamp."""
    if ed.packed is None or n > ed.packed:
        ed.packed, ed.packed_as_of, ed.packed_source = n, at, source
    elif n == ed.packed and at and (ed.packed_as_of is None or at > ed.packed_as_of):
        ed.packed_as_of, ed.packed_source = at, source


def _read_editions(rows: list[tuple], editions: dict[str, EditionPlan],
                   launch: date | None = None, tz: ZoneInfo | None = None,
                   source: str | None = None) -> None:
    """Rates and packed copies from any table that lists launch products by id."""
    for i, r in enumerate(rows):
        cells = [str(c or "").strip().lower() for c in r]
        pc = next((j for j, c in enumerate(cells) if c in ("product", "material", "product id")), None)
        if pc is None:
            continue
        header = {c: j for j, c in enumerate(cells) if c}
        title = " ".join(str(c or "") for row in rows[:i] for c in row).lower()
        at = _stamp(title, launch, tz) if tz else None
        rc = _col(header, "rate")
        kc = header.get("packed")
        if kc is None and "packed" in title:
            kc = header.get("qty")
        for row in rows[i + 1:]:
            pid = str(row[pc] or "").strip() if pc < len(row) else ""
            if pid not in editions:
                continue
            ed = editions[pid]
            if rc is not None and _num(row[rc]):
                ed.rate_per_hour = _num(row[rc])
            n = _num(row[kc]) if kc is not None else None
            if n is not None:
                _set_packed(ed, n, at, source)


def load(root: Path | None, tz: ZoneInfo) -> PackClock:
    if root is None:
        return PackClock()
    soony = root / "soony"
    products = _read_csv(soony / "master" / "products.csv")
    launch_products = {p["product_id"]: p for p in products if p.get("lifecycle") == "launch"}
    launch_dates = sorted(p.get("launch_date") for p in launch_products.values() if p.get("launch_date"))
    launch = date.fromisoformat(launch_dates[0]) if launch_dates else None

    editions: dict[str, EditionPlan] = {
        pid: EditionPlan(pid, p.get("name"), _num(p.get("day_one_qty"))) for pid, p in launch_products.items()
    }
    windows: list[tuple[datetime, datetime]] = []
    books = [b for d in ("context", "erp") if (soony / d).is_dir() for b in sorted((soony / d).glob("*.xlsx"))]
    for book in books:
        for sheet, rows in _rows(book).items():
            windows = windows or _windows(rows, launch, tz)
            _read_editions(rows, editions, launch, tz, f"{book.relative_to(root)} · {sheet}")
    if not windows and launch:
        windows = default_windows(launch, tz)
    # Packed copies only grow, so the highest figure across the plan, status sheets and the
    # pack-out log is the newest one. A log is complete up to the end of its last day.
    packed: dict[str, float] = {}
    last_day: dict[str, date] = {}
    log_file: dict[str, str] = {}
    for f in sorted((soony / "erp").glob("packout_log*.csv")) if (soony / "erp").is_dir() else []:
        for r in _read_csv(f):
            pid = r.get("product_id")
            if pid in editions:
                packed[pid] = packed.get(pid, 0) + (_num(r.get("units_packed")) or 0)
                log_file[pid] = str(f.relative_to(root))
                try:
                    d = date.fromisoformat(str(r.get("date") or "")[:10])
                    last_day[pid] = max(last_day.get(pid, d), d)
                except ValueError:
                    pass
    for pid, n in packed.items():
        d = last_day.get(pid)
        at = datetime(d.year, d.month, d.day, tzinfo=tz) + timedelta(days=1) if d else None
        _set_packed(editions[pid], n, at, log_file.get(pid))
    return PackClock(windows, editions)
"""
Price it: from the linked graph to copies at risk.

For every edition still being packed: remaining = day-one demand - packed. For every part in
its bill of materials: needed = remaining x quantity per copy. Usable stock = the latest book
stock minus what the evidence says is not really there or can't be used (live linker issues with
a stock effect). Arriving = inbound already on its way that lands in the DC before packing ends
and is not yet in that stock (see _arriving). Gap = needed - usable - arriving. Everything comes
from the data; nothing is typed in.
"""

import math
import re
from dataclasses import dataclass, field
from datetime import datetime, timedelta

import pandas as pd

from ask_soony.verifier.impact.timing import lead_hours, parse_moment, runs_dry, shift_windows

# Linker issues whose units are book stock that is not really usable
STOCK_EFFECT_RULES = {
    "delivery_vs_receipt": "booked but not delivered",
    "failed_lot_in_stock": "failed inspection",
    "remark_names_other_part": "wrong part booked",
    "old_revision_in_stock": "old revision, must not be packed",
}


@dataclass
class Deduction:
    reason: str
    units: float
    issue: str  # record id of the issue's record
    context: str


@dataclass
class PartNeed:
    part: str
    description: str | None
    editions: list[str]
    needed: float
    book_stock: float
    book_as_of: str | None
    deductions: list[Deduction] = field(default_factory=list)
    plan_status: str | None = None  # what the launch plan says ('ok', 'CHECK')
    supply: list[dict] = field(default_factory=list)  # options to close the gap
    per_copy: dict[str, float] = field(default_factory=dict)  # edition → parts per copy
    used_today: float | None = None
    rate_per_hour: float | None = None  # how fast the lines use it
    runs_dry: datetime | None = None  # None: lasts to the end of packing
    fixes: list[dict] = field(default_factory=list)  # supply that can arrive in time, with act-by
    # Inbound already on its way that lands before packing ends: counted as available.
    # Each: reference, quantity, eta, status, supplier_id, po_numbers, basis (see _arriving)
    arriving: list[dict] = field(default_factory=list)
    # Inbound due before packing ends that is NOT counted, with the reason (already in stock,
    # shipped short, supplier's paper not read yet, ...). Shown so nobody counts it twice.
    not_counted: list[dict] = field(default_factory=list)

    @property
    def usable(self) -> float:
        return max(self.book_stock - sum(d.units for d in self.deductions), 0)

    @property
    def arriving_in_time(self) -> float:
        return sum(a["quantity"] for a in self.arriving)

    @property
    def gap(self) -> float:
        """Needed minus usable stock minus inbound that lands before packing ends."""
        return max(self.needed - self.usable - self.arriving_in_time, 0)

    @property
    def gap_if_acted(self) -> float:
        """The gap left if every fix that can arrive in time is taken."""
        closable = sum(f["quantity"] for f in self.fixes if f["in_time"])
        return max(self.gap - closable, 0)


@dataclass
class Edition:
    product: str
    name: str | None
    launch_date: str | None
    day_one: float
    packed: float
    packed_as_of: str | None
    rate_per_hour: float | None

    @property
    def remaining(self) -> float:
        return max(self.day_one - self.packed, 0)


@dataclass
class Shortfall:
    editions: list[Edition]
    parts: list[PartNeed]
    excluded: list[dict]  # BOM parts not stocked separately, with the evidence
    now: datetime | None = None  # time of the newest stock figures
    packing_ends: datetime | None = None
    hours_left: float | None = None

    def at_risk(self, product: str, acted: bool = False) -> tuple[float, str | None]:
        """
        Copies of an edition at risk from parts only it uses, and the part that binds.
        acted=True: after every fix that can still arrive in time.
        """

        def gap(p: PartNeed) -> float:
            return p.gap_if_acted if acted else p.gap

        own = [p for p in self.parts if p.editions == [product] and gap(p) > 0]
        if not own:
            return 0, None
        worst = max(own, key=gap)
        return gap(worst), worst.part

    @property
    def shared_gaps(self) -> list[PartNeed]:
        return [p for p in self.parts if len(p.editions) > 1 and p.gap > 0]


def _latest(rows: list[dict]) -> dict | None:
    """The newest record by as_of; records without a date come last."""
    return max(rows, key=lambda r: r["as_of"] or "", default=None)


def _known_parts(records: pd.DataFrame) -> set[str]:
    return set(records[records.kind == "part"].material_id.dropna())


def _fitted_parts(records: pd.DataFrame, known: set[str]) -> dict[str, dict]:
    """
    Parts a supplier says it fits into another part ('fitted by supplier into CMP-...'), so they
    are never stocked on their own. Learned from the suppliers' own part lists.
    """
    fitted = {}
    for r in records[records.kind == "supplier_part"].to_dict("records"):
        note = r["attrs"].get("note") or ""
        others = [p for p in known if p != r["material_id"] and re.search(re.escape(p), note)]
        if others and re.search(r"fitted|included|built[- ]in|assembled", note, re.I):
            fitted[r["material_id"]] = {
                "inside": others[0],
                "evidence": note,
                "source": r["source"],
            }
    return fitted


def compute(records: pd.DataFrame, issues: pd.DataFrame) -> Shortfall:
    rows = records.to_dict("records")
    by_kind: dict[str, list[dict]] = {}
    for r in rows:
        by_kind.setdefault(r["kind"], []).append(r)

    # Editions: launch products with a day-one demand
    editions = []
    for product in by_kind.get("product", []):
        demand = product["attrs"].get("day_one_qty")
        if not demand:
            continue
        pid = product["material_id"]
        packed = _latest([r for r in by_kind.get("packed_count", []) if r["material_id"] == pid])
        plans = [r for r in by_kind.get("plan_edition", []) if r["material_id"] == pid]
        plan = _latest(plans)
        packed_qty = (packed or {}).get("attrs", {}).get("quantity")
        if packed_qty is None and plan:
            packed_qty = plan["attrs"].get("packed")
        rate = next(
            (p["attrs"]["rate_per_hour"] for p in plans if p["attrs"].get("rate_per_hour")), None
        )
        editions.append(
            Edition(
                pid,
                product["attrs"].get("name"),
                product["attrs"].get("launch_date"),
                demand,
                packed_qty or 0,
                (packed or plan or {}).get("as_of"),
                rate,
            )
        )
    remaining = {e.product: e.remaining for e in editions}

    # Needs from the bill of materials
    known = _known_parts(records)
    fitted = _fitted_parts(records, known)
    needs: dict[str, PartNeed] = {}
    excluded = []
    descriptions = {
        r["material_id"]: r["attrs"].get("description") for r in by_kind.get("part", [])
    }
    for line in by_kind.get("bom_line", []):
        parent, part = line["attrs"]["parent"], line["material_id"]
        if parent not in remaining:
            continue
        if part in fitted:
            excluded.append({"part": part, "edition": parent, **fitted[part]})
            continue
        need = needs.setdefault(part, PartNeed(part, descriptions.get(part), [], 0, 0, None))
        need.editions.append(parent)
        need.per_copy[parent] = line["attrs"].get("qty_per") or 1
        need.needed += remaining[parent] * need.per_copy[parent]

    # Book stock: the newest count per part; else the stock snapshot
    for part, need in needs.items():
        latest = _latest([r for r in by_kind.get("stock_count", []) if r["material_id"] == part])
        if latest:
            need.book_stock, need.book_as_of = latest["attrs"].get("quantity") or 0, latest["as_of"]
            need.used_today = latest["attrs"].get("used_today")
        else:
            batches = [r for r in by_kind.get("stock_batch", []) if r["material_id"] == part]
            need.book_stock = sum(r["attrs"].get("quantity") or 0 for r in batches)
            need.book_as_of = _latest(batches)["as_of"] if batches else None
        plan_part = _latest([r for r in by_kind.get("plan_part", []) if r["material_id"] == part])
        need.plan_status = plan_part["attrs"].get("status") if plan_part else None

    # Deductions: live issues with a stock effect
    for issue in issues.to_dict("records"):
        reason = STOCK_EFFECT_RULES.get(issue["rule"])
        units = issue.get("units")
        if (
            not reason
            or not issue.get("live")
            or units is None
            or (isinstance(units, float) and math.isnan(units))
        ):
            continue
        if issue["material_id"] in needs:
            needs[issue["material_id"]].deductions.append(
                Deduction(reason, float(units), issue["record_id"], issue.get("context") or "")
            )

    # Supply that could close a gap before launch
    launch = min((e.launch_date for e in editions if e.launch_date), default=None)
    for plan in by_kind.get("plan_inbound", []):
        need = needs.get(plan["material_id"])
        status = (plan["attrs"].get("status") or "").lower()
        if need is None:
            continue
        if "arrived" in status:  # at the port, not in stock yet: needs collecting
            need.supply.append(
                {
                    "kind": "at_port",
                    "quantity": plan["attrs"].get("quantity"),
                    "reference": plan["reference"],
                    "note": plan["attrs"].get("comment"),
                    "supplier_id": plan["supplier_id"],
                }
            )
        elif launch and plan["attrs"].get("eta") and plan["attrs"]["eta"] > launch:
            need.supply.append(
                {
                    "kind": "after_launch",
                    "quantity": plan["attrs"].get("quantity"),
                    "reference": plan["reference"],
                    "eta": plan["attrs"]["eta"],
                    "supplier_id": plan["supplier_id"],
                }
            )
    for reading in by_kind.get("reading", []):
        if reading["attrs"].get("doc_type") != "offer":
            continue
        for line in (
            r for r in by_kind.get("doc_line", []) if r["doc_path"] == reading["doc_path"]
        ):
            need = needs.get(line["material_id"])
            final = line["attrs"]["final"]
            quantity = next(
                (
                    final[k]
                    for k in (
                        "quantity_offered",
                        "quantity_confirmed",
                        "quantity_ordered",
                        "quantity_shipped",
                        "quantity_delivered",
                    )
--- provider factory ---
"""
Provider-neutral agent loop interface.

The agent only knows about text, images and tools. Each backend translates that into its own
API: llm/anthropic_backend.py (Anthropic SDK) and llm/openai_backend.py (OpenAI SDK, also for
OpenAI-compatible servers such as llama.cpp).
"""

from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Protocol

from ask_soony.extract import Image


@dataclass
class Tool:
    name: str
    description: str
    schema: dict


@dataclass
class RunResult:
    final_text: str
    tool_calls: int
    stop_reason: str
    usage: dict = field(default_factory=dict)


# Runs one tool call and returns the text result. Raising ToolError marks the result as an error.
ToolHandler = Callable[[str, dict], str]


class ToolError(Exception):
    pass


class Backend(Protocol):
    provider: str
    model: str

    def run(
        self,
        system: str,
        text: str,
        images: list[Image],
        tools: list[Tool],
        handler: ToolHandler,
        should_stop: Callable[[], bool],
        max_turns: int = 12,
    ) -> RunResult: ...


def make_backend(provider: str, model: str, api_key: str, base_url: str, effort: str) -> Backend:
    if provider == "anthropic":
        from ask_soony.llm.anthropic_backend import AnthropicBackend

        return AnthropicBackend(model=model, api_key=REDACTED, base_url=base_url, effort=effort)
    if provider in {"openai", "llamacpp", "openai-compatible"}:
        from ask_soony.llm.openai_backend import OpenAIBackend

        return OpenAIBackend(model=model, api_key=REDACTED, base_url=base_url, provider=provider)
    raise ValueError(f"unknown ASK_LLM_PROVIDER {provider!r}: use anthropic, openai or llamacpp")
